"use client";

import { useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation"; // ADDED: Next.js router for smooth navigation
import { RoleSlug } from "@/lib/role-slugs";

type AuthFormProps = {
  role: RoleSlug;
  heading: string;
  eyebrow: string;
  submitLabel?: string;
};

export default function AuthForm({
  role,
  heading,
  eyebrow,
  submitLabel = "Sign in",
}: AuthFormProps) {
  const [showPassword, setShowPassword] = useState(false);
  const [showWelcomeModal, setShowWelcomeModal] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [errorMessage, setErrorMessage] = useState("");
  const router = useRouter(); // ADDED: Initialize router

  const handleLogin = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSubmitting(true);
    setErrorMessage("");

    const formData = new FormData(e.currentTarget);
    const email = String(formData.get("email") || "");
    const password = String(formData.get("password") || "");
    const requestedRole = role.toUpperCase();

    try {
      const response = await fetch("/api/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({ email, password, role: requestedRole }),
      });

      const data = await response.json().catch(() => null);

      if (response.ok) {
        // FIX 1: Token ko browser ki local storage mein save karein
        if (data?.token) {
          localStorage.setItem("token", data.token);
        }

        setShowWelcomeModal(true);
        setTimeout(() => {
          // FIX 2: Next.js router ka use karna better state management ke liye
          const redirectPath = data?.redirectUrl || `/dashboard/${role}`;
          
          // Agar aapka Next.js middleware token read nahi kar pa raha, toh window.location.href use karein
          window.location.href = redirectPath; 
        }, 2500);
      } else {
        setErrorMessage(data?.message || data?.error || "Login failed. Please check your credentials.");
        setIsSubmitting(false);
      }
    } catch (error) {
      console.error("Login API Error:", error);
      setErrorMessage("Login failed. Please try again.");
      setIsSubmitting(false);
    }
  };

  return (
    <main className="min-h-screen bg-gray-50 text-gray-900 font-sans flex items-start justify-center pt-28 pb-12 px-4 relative">
      
      {/* --- WELCOME POPUP OVERLAY --- */}
      {showWelcomeModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-gray-900/40 backdrop-blur-sm transition-all duration-300">
          <div className="bg-white p-8 rounded-3xl shadow-2xl transform transition-all scale-100 border-b-4 border-emerald-500 max-w-sm w-full mx-4 text-center animate-in fade-in zoom-in duration-300">
            <div className="mx-auto flex items-center justify-center h-16 w-16 rounded-full bg-emerald-100 mb-5 shadow-inner">
              <svg className="h-8 w-8 text-emerald-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7" />
              </svg>
            </div>
            
            <h2 className="text-2xl font-extrabold text-gray-900 mb-2 capitalize">
              Welcome, {role}!
            </h2>
            <p className="text-gray-500 font-medium text-sm">
              Your dashboard is loading...
            </p>
            
            <div className="mt-6 flex justify-center">
              <svg className="animate-spin h-6 w-6 text-emerald-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
              </svg>
            </div>
          </div>
        </div>
      )}

      {/* Main Card Container */}
      <section className="w-full max-w-md bg-white rounded-3xl shadow-[0_8px_30px_rgb(0,0,0,0.08)] border border-gray-100 p-6 sm:p-10 transition-all mt-8">
        
        <div className="mb-8 text-center sm:text-left">
          <div className="inline-block px-3 py-1 mb-4 rounded-full bg-blue-50 border border-blue-100">
            <p className="text-xs font-bold uppercase tracking-[0.15em] text-blue-600">
              {eyebrow}
            </p>
          </div>
          <h1 className="text-3xl sm:text-4xl font-extrabold tracking-tight text-gray-900 mb-2">
            {heading}
          </h1>
          <p className="text-sm leading-relaxed text-gray-500">
            Welcome back to BNQinTECH. Please sign in to access your {role} dashboard.
          </p>
        </div>

        <form onSubmit={handleLogin} className="space-y-5">
          <input type="hidden" name="role" value={role} />
          {errorMessage ? (
            <div className="rounded-xl border border-red-100 bg-red-50 p-4 text-sm font-medium text-red-600">
              {errorMessage}
            </div>
          ) : null}
          
          <div className="space-y-1.5">
            <label htmlFor="email" className="block text-sm font-semibold text-gray-700 ml-1">
              Email Address
            </label>
            <div className="relative">
              <input
                id="email"
                name="email"
                type="email"
                autoComplete="email"
                required
                className="w-full rounded-xl border border-gray-300 bg-gray-50 px-4 py-3.5 text-sm text-gray-900 placeholder-gray-400 outline-none transition-all duration-300 focus:border-blue-500 focus:bg-white focus:ring-4 focus:ring-blue-500/10 hover:border-gray-400"
                placeholder="you@example.com"
              />
            </div>
          </div>

          <div className="space-y-1.5">
            <div className="flex items-center justify-between ml-1 pr-1">
              <label htmlFor="password" className="block text-sm font-semibold text-gray-700">
                Password
              </label>
              <Link 
                href={`/forgot-password?role=${role}`}
                className="text-sm font-semibold text-blue-600 hover:text-blue-700 hover:underline transition-all duration-200"
              >
                Forgot password?
              </Link>
            </div>
            
            <div className="relative group">
              <input
                id="password"
                name="password"
                type={showPassword ? "text" : "password"}
                autoComplete="current-password"
                required
                className="w-full rounded-xl border border-gray-300 bg-gray-50 py-3.5 pl-4 pr-12 text-sm text-gray-900 placeholder-gray-400 outline-none transition-all duration-300 focus:border-blue-500 focus:bg-white focus:ring-4 focus:ring-blue-500/10 hover:border-gray-400"
                placeholder="••••••••"
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute right-3 top-1/2 -translate-y-1/2 p-2 text-gray-400 hover:text-blue-600 transition-colors focus:outline-none rounded-lg hover:bg-gray-100"
              >
                {showPassword ? (
                  <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
                  </svg>
                ) : (
                  <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l3.59 3.59m0 0A9.953 9.953 0 0112 5c4.478 0 8.268 2.943 9.543 7a10.025 10.025 0 01-4.132 5.411m0 0L21 21" />
                  </svg>
                )}
              </button>
            </div>
          </div>

          <div className="pt-2">
            <button
              type="submit"
              disabled={isSubmitting}
              className="w-full rounded-xl bg-blue-600 px-4 py-3.5 text-sm font-bold text-white transition-all duration-300 hover:bg-blue-700 hover:shadow-lg focus:outline-none focus:ring-4 focus:ring-blue-600/30 active:scale-[0.98] disabled:opacity-70 flex justify-center items-center"
            >
              {isSubmitting ? (
                <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
              ) : null}
              {isSubmitting ? "Signing in..." : submitLabel}
            </button>
          </div>
        </form>

        <div className="mt-8 pt-6 border-t border-gray-100 text-center">
          <p className="text-sm text-gray-500">
            Don't have an account?{' '}
            <Link 
              href={`/register/${role}`} 
              className="font-bold text-blue-600 hover:text-blue-700 hover:underline transition-all duration-200 ml-1"
            >
              Sign up as {role === 'client' ? 'a Client' : 'a Partner'}
            </Link>
          </p>
        </div>

      </section>
    </main>
  );
}